def gen_inputs(ctx, device):
    import torch
    dt = getattr(torch, ctx["self__shape" and "self__dtype"])
    s = ctx["self__shape"]
    # Reproduce a non-contiguous source (transpose) to exercise the reshape copy path.
    inp = torch.randn(s[1], s[0], dtype=dt, device=device).T
    return {"self": inp}
